170	.ds-btn {
171	  display: inline-flex;
172	  align-items: center;
173	  justify-content: center;
174	  gap: 6px;
175	  padding: 10px 20px;
176	  min-width: 120px;
177	  font-family: var(--arxiv-font-sans);
178	  font-size: 14px;
179	  font-weight: 600;
180	  line-height: 1;
181	  text-decoration: none;
182	  cursor: pointer;
183	  border: 1.5px solid transparent;
184	  border-radius: 6px;
185	  transition: background 0.12s, border-color 0.12s, box-shadow 0.12s, transform 0.08s, color 0.12s;
186	}
187	.ds-btn:focus-visible {
188	  outline: 3px solid var(--arxiv-focus-ring);
189	  outline-offset: 2px;
190	}
191	
192	/* ── Primary (Open Blue) ─────────────────────────────────────────── */
193	.ds-btn-primary {
194	  background:
195	    linear-gradient(#a5d6fe, #a5d6fe) padding-box,
196	    linear-gradient(to bottom, #b0d5ed, #6ba8da) border-box;
197	  color: var(--arxiv-ink);
198	  box-shadow:
199	    inset 0 0 6px rgba(31, 94, 150, 0.20),
200	    0 1px 3px rgba(0, 0, 0, 0.12);
201	}
202	.ds-btn-primary:hover {
203	  background:
204	    linear-gradient(#c2e2ff, #c2e2ff) padding-box,
205	    linear-gradient(to bottom, #8fc1e8, #4a86b8) border-box;
206	  box-shadow:
207	    inset 0 0 8px rgba(31, 94, 150, 0.10),
208	    0 1px 3px rgba(0, 0, 0, 0.12);
209	}
210	.ds-btn-primary:active {
211	  transform: translateY(1px);
212	  background:
213	    linear-gradient(#a5d6fe, #a5d6fe) padding-box,
214	    linear-gradient(#6ba8da, #6ba8da) border-box;
215	  box-shadow: inset 0 0 10px rgba(31, 94, 150, 0.35);
216	}
