218	/* ── Secondary (white) ───────────────────────────────────────────── */
219	.ds-btn-secondary {
220	  background:
221	    linear-gradient(#ffffff, #ffffff) padding-box,
222	    linear-gradient(to bottom, #ddd8d2, #b3ada4) border-box;
223	  color: var(--arxiv-grey);
