238	  transform: translateY(1px);
239	  background:
240	    linear-gradient(#ffffff, #ffffff) padding-box,
241	    linear-gradient(var(--arxiv-grey-ui), var(--arxiv-grey-ui)) border-box;
242	  box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.13);
243	}
