245	/* ── Secondary on tinted surface (.on-tint modifier) ─────────────────
246	   Apply the `on-tint` class IN ADDITION to `.ds-btn-secondary` when
247	   the button sits inside a tinted section (e.g., the HTML reader's
248	   light-blue footer band). The default white fill creates too much
249	   contrast on a tinted surface and reads as "primary"; this variant
250	   swaps the fill to Card Grey — same luminance as the surface, warm
251	   hue — so the button reads as intentionally secondary via warm-on-
252	   cool material differentiation, not via low contrast.
253	   Hover brightens to Warm Wash (lighter step in the same warm family),
254	   echoing the primary button's brighten-on-hover behavior.
255	
256	   Validated 2026-05-22 in arxiv-mockups/arxiv-public/html-redesign.html
257	   footer ("Help improve HTML papers" section).
258	
259	   Example:
260	     <a class="ds-btn ds-btn-secondary on-tint" href="...">Submit a fix</a>
261	*/
262	.ds-btn-secondary.on-tint {
263	  background:
264	    linear-gradient(var(--arxiv-card-grey), var(--arxiv-card-grey)) padding-box,
265	    linear-gradient(to bottom, #ddd8d2, #b3ada4) border-box;
266	}
267	.ds-btn-secondary.on-tint:hover {
268	  background:
269	    linear-gradient(var(--arxiv-warm-wash), var(--arxiv-warm-wash)) padding-box,
