200	      <pre class="code-block">&lt;div class="ds-alert ds-alert-info" role="status"&gt;
201	  &lt;svg class="ds-alert-icon" aria-hidden="true"&gt;&lt;!-- icon --&gt;&lt;/svg&gt;
