214	  <script>
215	    (function () {
216	      var html = document.documentElement;
217	
218	      /* Surface token convention: public stylesheet uses the --arxiv- prefix. */
219	      var PREFIX = 'arxiv-';
220	      var STATES = [['Success','success'], ['Info','info'], ['Warning','warning'], ['Error / failure','error']];
221	
222	      function readVar(name) { return getComputedStyle(html).getPropertyValue(name).trim(); }
223	      function toRGB(value) {
224	        var probe = document.createElement('span');
225	        probe.style.color = value;
226	        document.body.appendChild(probe);
227	        var rgb = getComputedStyle(probe).color;
228	        probe.remove();
229	        return rgb.match(/[\d.]+/g).slice(0, 3).map(Number);
230	      }
231	      function hex(c) { return '#' + c.map(function (x) { return Math.round(x).toString(16).padStart(2, '0'); }).join(''); }
232	      function lum(c) {
233	        var f = c.map(function (v) { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); });
234	        return 0.2126 * f[0] + 0.7152 * f[1] + 0.0722 * f[2];
235	      }
236	      function ratio(a, b) { var L1 = lum(a), L2 = lum(b), hi = Math.max(L1, L2), lo = Math.min(L1, L2); return (hi + 0.05) / (lo + 0.05); }
237	      function grade(r) { return r >= 7 ? 'AAA' : r >= 4.5 ? 'AA' : r >= 3 ? 'AA Large' : null; }
238	      function cell(c) { return '<span class="swatch" style="background:' + hex(c) + '"></span><code>' + hex(c) + '</code>'; }
239	
240	      function render() {
241	        var rows = STATES.map(function (s) {
242	          var bg = toRGB(readVar('--' + PREFIX + s[1] + '-bg'));
243	          var bd = toRGB(readVar('--' + PREFIX + s[1] + '-border'));
244	          var fg = toRGB(readVar('--' + PREFIX + s[1] + '-fg'));
245	          var r = ratio(fg, bg), g = grade(r);
246	          var label = g ? '<span class="ratio-pass">' + r.toFixed(1) + ':1 ✓ ' + g + '</span>'
247	                        : '<span class="ratio-fail">' + r.toFixed(1) + ':1 ✗</span>';
248	          return '<tr><td class="state-name">' + s[0] + '</td><td>' + cell(bg) + '</td><td>' + cell(bd) + '</td><td>' + cell(fg) + '</td><td>' + label + '</td></tr>';
249	        }).join('');
250	        document.getElementById('token-rows').innerHTML = rows;
251	      }
252	
253	      render();
254	      /* Re-read if the OS flips light/dark while the page is open. */
255	      window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', render);
256	    })();
257	  </script>
