  line-height: 1.5;
  color: var(--arxiv-ink);
  overflow-y: auto;
  overscroll-behavior: contain;
}
.ds-popover[hidden] { display: none; }

.ds-popover-title {
  font-family: var(--arxiv-font-condensed);
  font-weight: 600;
  font-size: 11px;
  color: var(--arxiv-grey);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin: 0 0 8px;
  padding-right: 28px;  /* room for the close button */
}

.ds-popover-close {
  position: absolute;
  top: 6px;
  right: 8px;
  background: none;
  border: none;
  font-size: 22px;
  line-height: 1;
  color: var(--arxiv-grey);
  cursor: pointer;
  padding: 2px 8px;
  border-radius: 4px;
}
.ds-popover-close:hover {
  color: var(--arxiv-ink);
  background: var(--arxiv-active-bg);
}
