507	.ds-element-pill {
508	  position: absolute;
509	  display: flex;
510	  flex-direction: row;
511	  flex-wrap: wrap;
512	  align-items: center;
513	  justify-content: center;
514	  gap: 4px 14px;
515	  width: max-content;
516	  max-width: calc(100% - 16px);
517	  padding: 6px 14px;
518	  background: #ffffff;
519	  border: 1px solid var(--arxiv-pill-border);
520	  border-radius: 999px;
521	  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.10);
522	  opacity: 0;
523	  visibility: hidden;
524	  pointer-events: none;
525	  transition: opacity 0.18s ease, visibility 0s linear 0.18s;
526	  z-index: 2;
527	}
528	.ds-element-pill.is-revealed {
529	  opacity: 1;
