536	/* ═══════════════════════════════════════════════════════════════════════
537	   ALERT / STATUS MESSAGE  (.ds-alert)
538	   ───────────────────────────────────────────────────────────────────────
539	   Inline status banner — success / info / warning / error (failure).
540	   Token-driven via the --arxiv-{success,info,warning,error}-* families
541	   (see color-mapping.md "Status & alert colors — shared"). Structurally
542	   identical to the internal stylesheet's .ds-alert; only the token names
543	   differ (--arxiv- prefix here).
544	
545	   Color is never the sole signal — pair each variant with a distinct icon
546	   shape AND a leading word (WCAG 1.4.1). ARIA: role="status" for
547	   success/info (polite), role="alert" for warning/error (assertive);
548	   icons carry aria-hidden="true". Inline links inherit the variant color
549	   and stay underlined, per the link policy.
550	
551	   Promoted from arxiv-mockups/design-patterns/alert-styles.html (2026-05-28).
552	
553	   Example:
554	     <div class="ds-alert ds-alert-info" role="status">
555	       <svg class="ds-alert-icon" aria-hidden="true">…</svg>
556	       <div class="ds-alert-content">
557	         <p class="ds-alert-title">Viewing an older version</p>
558	         <p>A newer version of this paper exists — <a href="...">see v3</a>.</p>
559	       </div>
560	     </div>
561	   ═══════════════════════════════════════════════════════════════════════ */
562	
563	.ds-alert {
564	  display: flex;
565	  align-items: flex-start;
566	  gap: 11px;
567	  padding: 12px 14px;
568	  border: 1px solid;
569	  border-left-width: 4px;
570	  border-radius: 6px;
571	  font-family: var(--arxiv-font-sans);
572	  font-size: 13px;
573	  line-height: 1.5;
574	}
575	.ds-alert-icon {
576	  flex-shrink: 0;
577	  width: 20px;
578	  height: 20px;
579	  margin-top: 1px;
580	  stroke: currentColor;
581	  fill: none;
582	}
583	.ds-alert-content { margin: 0; min-width: 0; }
584	.ds-alert-title { font-weight: 700; margin: 0 0 2px; }
585	.ds-alert-content p { margin: 0; }
586	.ds-alert a {
587	  color: inherit;
588	  font-weight: 600;
589	  text-decoration: underline;
590	  text-underline-offset: 2px;
591	}
592	.ds-alert-dismiss {
593	  flex-shrink: 0;
594	  margin-left: auto;
595	  margin-top: -2px;
596	  background: none;
597	  border: none;
598	  cursor: pointer;
599	  color: inherit;
600	  opacity: 0.7;
601	  padding: 2px;
602	  border-radius: 3px;
603	  line-height: 0;
604	  transition: opacity 0.15s ease;
605	}
606	.ds-alert-dismiss:hover { opacity: 1; }
607	.ds-alert-dismiss:focus-visible { outline: 3px solid var(--arxiv-focus-ring); outline-offset: 2px; }
608	.ds-alert-dismiss svg { width: 16px; height: 16px; stroke: currentColor; fill: none; }
609	
610	/* Variants — bg + border + fg (icon uses currentColor = fg) */
611	.ds-alert-success { background: var(--arxiv-success-bg); border-color: var(--arxiv-success-border); color: var(--arxiv-success-fg); }
612	.ds-alert-info    { background: var(--arxiv-info-bg);    border-color: var(--arxiv-info-border);    color: var(--arxiv-info-fg); }
613	.ds-alert-warning { background: var(--arxiv-warning-bg); border-color: var(--arxiv-warning-border); color: var(--arxiv-warning-fg); }
614	.ds-alert-error   { background: var(--arxiv-error-bg);   border-color: var(--arxiv-error-border);   color: var(--arxiv-error-fg); }
615	
616	/* Dark mode — overrides the status tokens only. This is the first
617	   dark-aware block in the public stylesheet; broader public dark mode is
618	   still pending (color-mapping.md open question). Guarded by data-theme
619	   so a page can lock to light with <html data-theme="light">. */
620	@media (prefers-color-scheme: dark) {
621	  :root:not([data-theme="light"]) {
622	    --arxiv-link-blue:       #64b5f6;  /* 7.84:1 on Repository Brown ✓ AAA */
623	    --arxiv-link-hover:      #90caf9;
624	    --arxiv-link-visited:    #c084e0;  /* 6.30:1 on Repository Brown ✓ AA */
625	    --arxiv-success-bg:      #1e2b0d;
626	    --arxiv-success-border:  #8fbd3a;
627	    --arxiv-success-fg:      #c5e1a5;  /* 10.4:1 ✓ AAA */
628	    --arxiv-info-bg:         #132433;
629	    --arxiv-info-border:     #64b5f6;
630	    --arxiv-info-fg:         #90caf9;  /* 9.0:1 ✓ AAA */
631	    --arxiv-warning-bg:      #2e2410;
632	    --arxiv-warning-border:  #e8b800;
633	    --arxiv-warning-fg:      #ffe082;  /* 11.8:1 ✓ AAA */
634	    --arxiv-error-bg:        #2d1414;
635	    --arxiv-error-border:    #e57373;
636	    --arxiv-error-fg:        #ef9a9a;  /* 8.0:1 ✓ AAA */
637	  }
638	}
639	
640	/* OS accessibility signals. forced-colors: the OS replaces our palette
641	   and the hues collapse, but icon shape + leading word still carry meaning
642	   and icons follow system text color; pin links to LinkText. Never set
643	   forced-color-adjust:none. */
644	@media (forced-colors: active) {
645	  .ds-alert a { color: LinkText; }
646	}
647	@media (prefers-reduced-motion: reduce) {
648	  .ds-alert-dismiss { transition: none; }
649	}
