651	/* ═══════════════════════════════════════════════════════════════════════
652	   ACCORDION  (.ds-acc / .ds-acc-stack / .ds-acc-body / .ds-acc-rail)
653	   ───────────────────────────────────────────────────────────────────────
654	   Native <details>/<summary> disclosure — no JS, keyboard and screen-
655	   reader semantics for free, and find-in-page can auto-expand panels.
656	   A +/− glyph replaces the default marker. Two dressings, one element:
657	
658	     - Card (default): white surface, hairline border, 6px radius —
659	       stands alone on the page. Stack several in .ds-acc-stack (8px gap).
660	     - Rail (.ds-acc-rail, added to .ds-acc): card chrome dropped —
661	       background, border, and radius go; the surrounding rail's hairline
662	       dividers do the separating. Internals go single-column for the
663	       narrow rail, and the +/− marker turns Link Blue so closed
664	       disclosures still read as interactive (Open Blue is too light
665	       for a glyph).
666	
667	   Body internals: a <dl> inside .ds-acc-body gets the standard metadata
668	   layout — condensed-caps <dt> labels beside regular <dd> values
669	   (two-column in cards, single-column in the rail variant).
670	
671	   Content rule (organizing-content.html): never put must-see information
672	   ONLY inside a closed accordion — required warnings also surface in
673	   always-visible flow. Default state is closed; a single most-relevant
674	   panel may start open. Open state is not persisted.
675	
676	   Adds over the mockup source: a :focus-visible ring on the summary, and
677	   the rail summary grows its hit area to the 24px target-size floor via
678	   the padding + negative-margin technique (DESIGN-POLICIES.md, Chrome
679	   and interaction structure) with no layout change. No transitions —
680	   nothing for prefers-reduced-motion to disable.
681	
682	   Validated 2026-06-22 → 2026-07-27 as .mg-acc in
683	   mockups/merged-abstract-reader.html (paper-info card group + abstract
684	   rail); treatment agreed on design-patterns/organizing-content.html.
685	
686	   Example:
687	     <div class="ds-acc-stack">
688	       <details class="ds-acc" open>
689	         <summary>Paper information</summary>
690	         <div class="ds-acc-body">
691	           <dl>
692	             <dt>arXiv ID</dt><dd><a href="…">2604.22725</a></dd>
693	             <dt>License</dt><dd><a href="…">CC BY 4.0</a></dd>
694	           </dl>
695	         </div>
696	       </details>
697	     </div>
698	   ═══════════════════════════════════════════════════════════════════════ */
699	
700	.ds-acc-stack { display: flex; flex-direction: column; gap: 8px; }
701	.ds-acc {
702	  background: #fff;
703	  border: 1px solid var(--arxiv-border-light);
704	  border-radius: 6px;
705	  font-family: var(--arxiv-font-sans);
706	}
707	.ds-acc > summary {
708	  cursor: pointer;
709	  list-style: none;
710	  font-size: 0.92rem;
711	  font-weight: 600;
712	  color: var(--arxiv-ink);
713	  padding: 11px 16px;
714	  display: flex;
715	  align-items: center;
716	  gap: 10px;
717	}
718	.ds-acc > summary::-webkit-details-marker { display: none; }
719	.ds-acc > summary::marker { content: ""; }
720	.ds-acc > summary::after {
721	  content: "+";
722	  content: "+" / "";  /* alt-text form: the glyph is decorative to AT —
723	                         <details> already announces expanded/collapsed */
724	  margin-left: auto;
725	  font-weight: 400;
726	  color: var(--arxiv-grey);
727	  font-size: 1.25rem;
728	  line-height: 1;
729	}
730	.ds-acc[open] > summary::after { content: "−"; content: "−" / ""; }
731	.ds-acc[open] > summary { border-bottom: 1px solid var(--arxiv-border-light); }
732	.ds-acc > summary:focus-visible {
733	  outline: 3px solid var(--arxiv-focus-ring);
734	  outline-offset: -2px;  /* ring sits inside the card edge */
735	  border-radius: 6px;
736	}
737	.ds-acc-body { padding: 14px 16px 16px; font-size: 0.85rem; color: var(--arxiv-ink); }
738	.ds-acc-body dl { display: grid; grid-template-columns: max-content 1fr; gap: 7px 18px; margin: 0; }
739	.ds-acc-body dt { font-family: var(--arxiv-font-condensed); text-transform: uppercase; font-size: 0.7rem; letter-spacing: 0.04em; color: var(--arxiv-grey); white-space: nowrap; padding-top: 2px; }
740	.ds-acc-body dd { margin: 0; }
741	.ds-acc-body a { color: var(--arxiv-link-blue); }
742	
743	/* Rail variant — chrome dropped; the rail's hairlines separate. */
744	.ds-acc-rail { background: transparent; border: 0; border-radius: 0; }
745	.ds-acc-rail > summary {
746	  font-size: 0.82rem;
747	  /* 4px padding + matching negative margin: the ~20px text line grows to
748	     a ≥24px hit target with zero layout shift (target-size floor). */
749	  padding: 4px 0;

